<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Netzwerk – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:900px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.person{border:1px solid #e1e7ed;border-radius:10px;padding:13px}.muted{color:#66758a}</style></head><body><main><p><a href="/community">← Community</a></p><h1>Dein Netzwerk</h1><div class="grid"><section class="card"><h2>Du folgst</h2><?php foreach($network['following'] as $p):?><div class="person"><a href="/community/u/<?= rawurlencode($p['username']) ?>"><strong>@<?= $e($p['username']) ?></strong></a><br><small class="muted">seit <?= $e($p['created_at']) ?></small></div><?php endforeach;?><?php if(!$network['following']):?><p class="muted">Du folgst noch niemandem.</p><?php endif;?></section><section class="card"><h2>Follower</h2><?php foreach($network['followers'] as $p):?><div class="person"><a href="/community/u/<?= rawurlencode($p['username']) ?>"><strong>@<?= $e($p['username']) ?></strong></a><br><small class="muted">seit <?= $e($p['created_at']) ?></small></div><?php endforeach;?><?php if(!$network['followers']):?><p class="muted">Noch keine Follower.</p><?php endif;?></section></div></main></body></html>